pub fn kernel_provides_procfs(kernel: KernelFamily) -> bool {
    match kernel.clone() {
    KernelFamily::Linux => true,
    KernelFamily::LinuxGuestOnWindows => true,
    KernelFamily::Darwin => false,
    KernelFamily::WindowsNt => false,
}
}

